[Resource from github at repo://missingbulb/EdFringeNow/sha/2f5377b99c9f71809c9a08d0d94e8b9d79ccdd45/contents/.claudinite-settings.json] {
  "packs": [
    {
      "id": "basics",
      "version": "60924.1"
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60924.1"
    },
    {
